create table if not exists jobs (
 id uuid primary key default gen_random_uuid(),session_id text not null,raw_request text not null,brief jsonb,state text not null default 'DRAFT',chosen_quote_id uuid,booked_slot timestamptz,payout_email_shown_at timestamptz,approved_book_at timestamptz,approved_done_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists businesses(id uuid primary key default gen_random_uuid(),job_id uuid not null references jobs(id),name text not null,phone text not null,rating numeric,source_url text,payout_email text,is_bot boolean not null default false);
create table if not exists calls(id uuid primary key default gen_random_uuid(),job_id uuid not null references jobs(id),business_id uuid references businesses(id),purpose text not null check(purpose in ('quote','confirm','completion')),provider_sid text unique,status text not null default 'queued',started_at timestamptz,ended_at timestamptz,consent_to_record boolean not null default false,recording_url text,transcript jsonb not null default '[]');
create unique index if not exists one_quote_call on calls(job_id,business_id) where purpose='quote';
create table if not exists quotes(id uuid primary key default gen_random_uuid(),call_id uuid not null unique references calls(id),business_id uuid not null references businesses(id),price_cents int check(price_cents>=0),currency text not null default 'USD',earliest_slot timestamptz,includes text[] not null default '{}',guarantee text,willing_to_negotiate boolean,confidence numeric not null check(confidence between 0 and 1),declined boolean not null default false);
create table if not exists payments(id uuid primary key default gen_random_uuid(),job_id uuid not null references jobs(id),kind text not null check(kind in ('order','authorization','reauthorization','capture','void','payout','invoice')),paypal_id text,status text not null,amount_cents int check(amount_cents>=0),request_id text not null unique,raw jsonb not null,created_at timestamptz not null default now());
create table if not exists events(id bigserial primary key,job_id uuid not null references jobs(id),type text not null,from_state text,to_state text,payload jsonb,created_at timestamptz not null default now());
create table if not exists webhook_events(id text primary key,provider text not null,received_at timestamptz not null default now(),payload jsonb not null);
create table if not exists effects(id bigserial primary key,job_id uuid not null references jobs(id),name text not null,payload jsonb not null default '{}',created_at timestamptz not null default now(),dispatched_at timestamptz);
